import itertools
import networkx as nx
import random

def check_graph(edges, n_vertices=15, k=8):
    G = nx.Graph()
    G.add_nodes_from(range(n_vertices))
    G.add_edges_from(edges)
    max_edges_in_k = 0
    for subset in itertools.combinations(range(n_vertices), k):
        subgraph = G.subgraph(subset)
        max_edges_in_k = max(max_edges_in_k, subgraph.number_of_edges())
    return max_edges_in_k

all_possible_edges = list(itertools.combinations(range(15), 2))

def greedy_graph(n_vertices=15, num_edges=56, k=8, max_m=15):
    G = nx.Graph()
    G.add_nodes_from(range(n_vertices))
    edges = []

    k_sets = list(itertools.combinations(range(n_vertices), k))
    edge_to_k_sets = {edge: [] for edge in all_possible_edges}
    for i, k_set in enumerate(k_sets):
        for edge in itertools.combinations(k_set, 2):
            edge_to_k_sets[edge].append(i)

    k_set_edge_counts = [0] * len(k_sets)

    random.shuffle(all_possible_edges)

    for edge in all_possible_edges:
        if len(edges) == num_edges:
            break

        can_add = True
        for k_set_idx in edge_to_k_sets[edge]:
            if k_set_edge_counts[k_set_idx] + 1 > max_m:
                can_add = False
                break

        if can_add:
            edges.append(edge)
            for k_set_idx in edge_to_k_sets[edge]:
                k_set_edge_counts[k_set_idx] += 1

    return edges, len(edges)

